#pragma once
#include <juce_audio_utils/juce_audio_utils.h>
#include <vector>
#include <map>
#include <mutex>
#include "Library.h"
struct SequenceNote {int id=0,pitch=60,velocity=100,channel=1;double beat=0,length=.25;int sourceRegion=0;};
struct SequenceClip {
 std::vector<SequenceNote> notes;int bars=4,key=-1;int beatLength=0;bool minor=false,manualKey=false;juce::String path;uint64_t revision=1;int nextId=1;bool dirty=false;double loopStart=0,loopLength=0,changedAt=0;
 void makeMonophonic(){auto ranked=notes;std::stable_sort(ranked.begin(),ranked.end(),[](auto a,auto b){if(a.length!=b.length)return a.length>b.length;if(a.velocity!=b.velocity)return a.velocity>b.velocity;return a.beat<b.beat;});std::map<double,SequenceNote> accepted;for(auto n:ranked){if(!std::isfinite(n.beat)||!std::isfinite(n.length)||n.length<=0)continue;double end=n.beat+n.length,cursor=n.beat,best=n.beat,bestLength=0;auto it=accepted.lower_bound(n.beat);if(it!=accepted.begin())--it;for(;it!=accepted.end()&&it->first<end-1e-9;++it){auto other=it->second;double stop=other.beat+other.length;if(stop<=cursor+1e-9)continue;double gap=juce::jmin(end,other.beat)-cursor;if(gap>bestLength){best=cursor;bestLength=gap;}cursor=juce::jmax(cursor,stop);if(cursor>=end)break;}if(end-cursor>bestLength){best=cursor;bestLength=end-cursor;}if(bestLength+1e-9<n.length*.5||bestLength<1e-6)continue;n.beat=best;n.length=bestLength;accepted[n.beat]=n;}std::vector<SequenceNote> result;for(auto& entry:accepted){auto n=entry.second;if(!result.empty()){auto previous=result.back();double gap=n.beat-(previous.beat+previous.length);if(previous.pitch!=n.pitch&&previous.length<=.125&&n.length>=previous.length*4&&gap>=-1e-8&&gap<=.03125&&n.beat-previous.beat<=.15625){double end=n.beat+n.length;n.beat=previous.beat;n.length=end-n.beat;result.pop_back();}}result.push_back(n);}notes=std::move(result);}
 double beats()const{return loopLength>0?loopLength:beatLength>0?beatLength:bars*4.;}
 double loopEnd()const{return loopStart+beats();}
 double timelineBeats()const{double end=loopEnd();for(auto n:notes)end=juce::jmax(end,n.beat+n.length);return juce::jlimit(1.,4096.,std::ceil(end));}
 void setLoop(double begin,double end){loopStart=juce::jlimit(0.,2048.-.015625,begin);loopLength=juce::jlimit(.015625,2048.-loopStart,end-loopStart);if(beatLength>0)beatLength=juce::jmax(1,(int)std::ceil(loopLength));else bars=juce::jmax(1,(int)std::ceil(loopLength/4));}
 void setLength(double length){loopLength=juce::jlimit(.015625,2048.-loopStart,length);if(beatLength>0)beatLength=juce::jmax(1,(int)std::ceil(loopLength));else bars=juce::jmax(1,(int)std::ceil(loopLength/4));}
 void extendTo(double end){if(end<=loopEnd())return;loopLength=0;end-=loopStart;if(beatLength>0)beatLength=juce::jlimit(1,2048,(int)std::ceil(end));else bars=juce::jlimit(1,512,(int)std::ceil(end/4));}
 static bool midi(juce::File f){return f.hasFileExtension("mid;midi");}
 static int inferKey(const std::vector<SequenceNote>& notes,bool& minor){double hist[12]{};for(auto n:notes)hist[n.pitch%12]+=n.length*n.velocity;if(notes.empty())return -1;static const double major[]{6.35,2.23,3.48,2.33,4.38,4.09,2.52,5.19,2.39,3.66,2.29,2.88},min[]{6.33,2.68,3.52,5.38,2.60,3.53,2.54,4.75,3.98,2.69,3.34,3.17};double best=-1;int result=0;for(int mode=0;mode<2;++mode)for(int root=0;root<12;++root){double score=0;for(int p=0;p<12;++p)score+=hist[(p+root)%12]*(mode?min[p]:major[p]);if(score>best){best=score;result=root;minor=mode!=0;}}return result;}
 bool fromMidi(juce::MidiFile file){int ppq=file.getTimeFormat();if(ppq<=0)return false;SequenceClip c;double end=0;std::unique_ptr<juce::XmlElement> savedLoop;for(int t=0;t<file.getNumTracks();++t){auto* track=file.getTrack(t);for(int i=0;i<track->getNumEvents();++i){auto* e=track->getEventPointer(i);auto m=e->message;end=juce::jmax(end,m.getTimeStamp()/ppq);if(m.isTextMetaEvent()&&m.getTextFromTextMetaEvent().startsWith("<SliceGroupsMidi "))savedLoop=juce::parseXML(m.getTextFromTextMetaEvent());if(m.isKeySignatureMetaEvent()){static const int major[]{0,7,2,9,4,11,6,1};int sf=m.getKeySignatureNumberOfSharpsOrFlats();c.minor=!m.isKeySignatureMajorKey();int k=sf>=0?major[juce::jlimit(0,7,sf)]:((12-(major[juce::jlimit(0,7,-sf)]))%12);c.key=(k+(c.minor?9:0))%12;}if(!m.isNoteOn()||!e->noteOffObject)continue;double b=m.getTimeStamp()/ppq,d=e->noteOffObject->message.getTimeStamp()/ppq-b;if(b<0||d<=0||!std::isfinite(b)||!std::isfinite(d))continue;if(c.notes.size()>=8192)return false;c.notes.push_back({c.nextId++,m.getNoteNumber(),(int)m.getVelocity(),m.getChannel(),b,d});}}
 if(c.notes.empty()&&!savedLoop)return false;if(end>4096)return false;c.bars=juce::jlimit(1,512,(int)std::ceil((end-1e-7)/4));if(end>0&&std::abs(end-std::round(end))<1e-6&&((int)std::round(end))%4)c.beatLength=juce::jlimit(1,2048,(int)std::round(end));if(c.key<0)c.key=inferKey(c.notes,c.minor);if(savedLoop){c.bars=juce::jlimit(1,512,savedLoop->getIntAttribute("bars",c.bars));c.beatLength=juce::jlimit(0,2048,savedLoop->getIntAttribute("beatLength"));c.setLoop(savedLoop->getDoubleAttribute("loopStart"),savedLoop->getDoubleAttribute("loopEnd",c.beats()));c.manualKey=savedLoop->getBoolAttribute("manualKey");}c.revision=revision+1;*this=std::move(c);return true;}
 bool load(juce::File f){if(f.getSize()>8*1024*1024)return false;auto stream=f.createInputStream();juce::MidiFile file;if(!stream||!file.readFrom(*stream))return false;if(!fromMidi(file))return false;path=f.getFullPathName();resolveFileKey();return true;}
 juce::MidiFile midiFile(bool document=false)const{juce::MidiMessageSequence s;if(document){juce::XmlElement meta("SliceGroupsMidi");meta.setAttribute("bars",bars);meta.setAttribute("beatLength",beatLength);meta.setAttribute("loopStart",loopStart);meta.setAttribute("loopEnd",loopEnd());meta.setAttribute("manualKey",manualKey);s.addEvent(juce::MidiMessage::textMetaEvent(1,meta.toString(juce::XmlElement::TextFormat().singleLine().withoutHeader())),0);}if(key>=0){int sf=0;double best=99;for(int a=-7;a<=7;++a){int major=(a*7%12+12)%12,k=(major+(minor?9:0))%12;if(k==key&&std::abs(a)<best){best=std::abs(a);sf=a;}}s.addEvent(juce::MidiMessage::keySignatureMetaEvent(sf,minor),0);}s.addEvent(juce::MidiMessage::timeSignatureMetaEvent(4,4),0);double first=document?0:loopStart,last=document?timelineBeats():loopEnd();for(auto n:notes)if(n.beat>=first&&n.beat<last){s.addEvent(juce::MidiMessage::noteOn(n.channel,n.pitch,(juce::uint8)n.velocity),(n.beat-first)*960);s.addEvent(juce::MidiMessage::noteOff(n.channel,n.pitch),(juce::jmin(last,n.beat+n.length)-first)*960);}s.addEvent(juce::MidiMessage::endOfTrack(),(last-first)*960);s.updateMatchedPairs();juce::MidiFile file;file.setTicksPerQuarterNote(960);file.addTrack(s);return file;}
 bool save(juce::File f){juce::TemporaryFile temp(f);{auto stream=temp.getFile().createOutputStream();if(!stream||!midiFile(true).writeTo(*stream))return false;stream->flush();if(stream->getStatus().failed())return false;}if(!temp.overwriteTargetFileWithTemporary())return false;path=f.getFullPathName();dirty=false;return true;}
 juce::String stateText()const{juce::XmlElement x("Root");write(x);return x.toString();}
 void changed(){dirty=true;changedAt=juce::Time::getMillisecondCounterHiRes();++revision;}
 void transpose(int delta){if(notes.empty())return;int lo=127,hi=0;for(auto n:notes){lo=juce::jmin(lo,n.pitch);hi=juce::jmax(hi,n.pitch);}delta=juce::jlimit(-lo,127-hi,delta);for(auto& n:notes)n.pitch+=delta;if(key>=0)key=(key+delta%12+12)%12;changed();}
 static double snapped(double beat,double grid,bool free){return free?beat:std::round(beat/grid)*grid;}
 void write(juce::XmlElement& root)const{auto* x=root.createNewChildElement("sequence");x->setAttribute("loopStart",loopStart);x->setAttribute("loopLength",loopLength);x->setAttribute("bars",bars);x->setAttribute("beatLength",beatLength);x->setAttribute("key",key);x->setAttribute("minor",minor);x->setAttribute("manualKey",manualKey);x->setAttribute("path",path);for(auto n:notes){auto* e=x->createNewChildElement("note");e->setAttribute("sourceRegion",n.sourceRegion);e->setAttribute("pitch",n.pitch);e->setAttribute("velocity",n.velocity);e->setAttribute("channel",n.channel);e->setAttribute("beat",n.beat);e->setAttribute("length",n.length);}}
 void read(const juce::XmlElement* x){if(!x){*this={};return;}SequenceClip c;c.loopStart=juce::jlimit(0.,2048.-.015625,x->getDoubleAttribute("loopStart"));c.loopLength=juce::jlimit(0.,2048.-c.loopStart,x->getDoubleAttribute("loopLength"));c.bars=juce::jlimit(1,512,x->getIntAttribute("bars",4));c.beatLength=juce::jlimit(0,2048,x->getIntAttribute("beatLength",0));c.key=juce::jlimit(-1,11,x->getIntAttribute("key",-1));c.minor=x->getBoolAttribute("minor");c.manualKey=x->getBoolAttribute("manualKey");c.path=x->getStringAttribute("path");for(auto* e:x->getChildIterator()){double b=e->getDoubleAttribute("beat"),d=e->getDoubleAttribute("length");if(e->hasTagName("note")&&c.notes.size()<8192&&std::isfinite(b)&&std::isfinite(d)&&b>=0&&d>0)c.notes.push_back({c.nextId++,juce::jlimit(0,127,e->getIntAttribute("pitch")),juce::jlimit(1,127,e->getIntAttribute("velocity",100)),juce::jlimit(1,16,e->getIntAttribute("channel",1)),b,juce::jmin(d,2048.),e->getIntAttribute("sourceRegion")});}c.revision=revision+1;*this=std::move(c);}
 void resolveFileKey(){if(path.isEmpty()||!midi(juce::File(path)))return;auto file=juce::File(path);auto resolved=LibraryStore::resolveMusicalKey(file,{key,minor?1:0},true);key=resolved.root<0?-1:resolved.root;minor=resolved.minor();manualKey=LibraryStore::musicalKeyOverride(file).root!=-2;}
 struct FileKeyInfo{juce::int64 stamp=0,size=0;int key=-1;bool minor=false;uint64_t metadataRevision=0;};
 static FileKeyInfo fileKeyInfo(juce::File f){auto detected=LibraryStore::resolveMusicalKey(f,{},true);if(detected.root!=-2)return {0,0,detected.root<0?-1:detected.root,detected.minor(),LibraryStore::kindRevision("musical-keys.json").load()};static std::mutex mutex;static std::map<juce::String,FileKeyInfo> cache;auto stamp=f.getLastModificationTime().toMilliseconds(),size=f.getSize();{std::lock_guard<std::mutex> g(mutex);auto it=cache.find(f.getFullPathName());if(it!=cache.end()&&it->second.stamp==stamp&&it->second.size==size)return it->second;}SequenceClip c;juce::MidiFile midi;auto stream=size<=8*1024*1024?f.createInputStream():nullptr;bool loaded=stream&&midi.readFrom(*stream)&&c.fromMidi(midi);FileKeyInfo value{stamp,size,loaded?c.key:-1,loaded&&c.minor,0};{std::lock_guard<std::mutex> g(mutex);if(cache.size()>=8192)cache.erase(cache.begin());cache[f.getFullPathName()]=value;}return value;}
 static int fileKey(juce::File f){return fileKeyInfo(f).key;}
};
struct MasterSequenceKey{std::atomic<bool> enabled{false};std::atomic<int> key{0};std::atomic<bool> minor{false};};

// Tickets are allocated at enqueue time; a stale writer cannot replace a newer snapshot.
struct MidiSaveTickets510 {
 inline static std::mutex mutex;inline static std::map<juce::String,uint64_t> latest;inline static uint64_t serial=0;
 static uint64_t ticket(juce::File file){std::lock_guard<std::mutex> g(mutex);return latest[file.getFullPathName()]=++serial;}
 static bool current(juce::File file,uint64_t token){std::lock_guard<std::mutex> g(mutex);return latest[file.getFullPathName()]==token;}
 static bool write(SequenceClip& clip,juce::File file,uint64_t token,bool mustExist){std::lock_guard<std::mutex> g(mutex);if(latest[file.getFullPathName()]!=token)return true;if(!LibraryStore::editable(file)||(mustExist&&!file.existsAsFile())||(file.existsAsFile()&&!file.hasWriteAccess()))return false;return clip.save(file);}
};
